   149→      suggestion: '意味のあるアプリケーション名を指定してください',
   150→    });
   151→  }
   152→
   153→  const validModes = ['workflow', 'advanced-chat', 'completion', 'agent-chat'];
   154→  if (!app.mode || !validModes.includes(app.mode)) {
   155→    context.issues.push({
   156→      level: 'error',
   157→      path: 'app.mode',
   158→      message: `無効なアプリケーションモード: ${app.mode}`,
   159→      suggestion: `有効なモード: ${validModes.join(', ')}`,
   160→    });
   161→  }
   162→
   163→  if (app.icon && !isValidEmoji(app.icon)) {
   164→    context.issues.push({
   165→      level: 'warning',
   166→      path: 'app.icon',
   167→      message: 'アイコンが有効な絵文字ではありません',
   168→      suggestion: 'Unicode絵文字を使用してください',
   169→    });
   170→  }
