   172→  if (app.icon_background && !isValidHexColor(app.icon_background)) {
   173→    context.issues.push({
   174→      level: 'warning',
   175→      path: 'app.icon_background',
   176→      message: '背景色が有効な16進数カラーコードではありません',
   177→      suggestion: '#RRGGBB形式で指定してください（例: #EFF1F5）',
