   193→      return;
   194→    }
   195→
   196→    if (!dsl.workflow.graph) {
   197→      context.issues.push({
   198→        level: 'error',
   199→        path: 'workflow.graph',
   200→        message: 'ワークフローグラフの定義が必須です',
   201→        suggestion: 'nodes と edges を含む graph セクションを追加してください',
