   223→  nodes.forEach((node, index) => {
   224→    if (!node.id) {
   225→      context.issues.push({
   226→        level: 'error',
   227→        path: `workflow.graph.nodes[${index}].id`,
   228→        message: 'ノードIDが必須です',
   229→        suggestion: '各ノードに一意のIDを設定してください',
   230→      });
   231→      return;
   232→    }
   233→
   234→    if (nodeIds.has(node.id)) {
   235→      context.issues.push({
   236→        level: 'error',
   237→        path: `workflow.graph.nodes[${index}].id`,
   238→        message: `重複するノードID: ${node.id}`,
   239→        suggestion: '各ノードのIDは一意である必要があります',
   240→      });
   241→    }
   242→    nodeIds.add(node.id);
   243→
   244→    // ノードタイプの検証
   245→    if (!node.type) {
   246→      context.issues.push({
   247→        level: 'error',
   248→        path: `workflow.graph.nodes[${index}].type`,
   249→        message: 'ノードタイプが必須です',
   250→        suggestion: `有効なノードタイプ: ${Object.values(NODE_TYPES).join(', ')}`,
   251→      });
   252→      return;
   253→    }
   254→
   255→    if (!Object.values(NODE_TYPES).includes(node.type as NodeType)) {
   256→      context.issues.push({
   257→        level: 'error',
   258→        path: `workflow.graph.nodes[${index}].type`,
   259→        message: `無効なノードタイプ: ${node.type}`,
   260→        suggestion: `有効なノードタイプ: ${Object.values(NODE_TYPES).join(', ')}`,
   261→      });
   262→      return;
   263→    }
   264→
   265→    // ノードタイプ固有の検証
   266→    validateNodeData(context, node, index);
   267→  });
   268→}
