   270→function validateNodeData(context: ValidationContext, node: any, index: number): void {
   271→  const validation = NODE_VALIDATIONS[node.type as NodeType];
   272→  if (!validation) return;
   273→
   274→  if (!node.data) {
   275→    context.issues.push({
   276→      level: 'error',
   277→      path: `workflow.graph.nodes[${index}].data`,
   278→      message: 'ノードのdataフィールドが必須です',
   279→      suggestion: `${node.type}ノードに必要なデータを設定してください`,
   280→    });
   281→    return;
   282→  }
   283→
   284→  // 必須フィールドのチェック
   285→  validation.required.forEach((field) => {
   286→    if (!hasNestedProperty(node.data, field)) {
   287→      context.issues.push({
   288→        level: 'error',
   289→        path: `workflow.graph.nodes[${index}].data.${field}`,
   290→        message: `${node.type}ノードでは${field}フィールドが必須です`,
   291→        suggestion: `必須フィールド ${field} を設定してください`,
   292→      });
   293→    }
   294→  });
   295→
   296→  // ノードタイプ固有の詳細検証
   297→  switch (node.type) {
   298→    case NODE_TYPES.LLM:
   299→      validateLLMNode(context, node, index);
   300→      break;
   301→    case NODE_TYPES.HTTP_REQUEST:
   302→      validateHTTPNode(context, node, index);
   303→      break;
   304→  }
   305→}
