   307→function validateLLMNode(context: ValidationContext, node: any, index: number): void {
   308→  if (node.data.model) {
   309→    const { model } = node.data;
   310→
   311→    if (!model.provider) {
   312→      context.issues.push({
   313→        level: 'error',
   314→        path: `workflow.graph.nodes[${index}].data.model.provider`,
   315→        message: 'LLMプロバイダーが必須です',
   316→        suggestion: 'openai, anthropic などのプロバイダーを指定してください',
   317→      });
   318→    }
   319→
   320→    if (!model.name) {
   321→      context.issues.push({
   322→        level: 'error',
   323→        path: `workflow.graph.nodes[${index}].data.model.name`,
   324→        message: 'モデル名が必須です',
   325→        suggestion: 'gpt-4, claude-3 などのモデル名を指定してください',
   326→      });
   327→    }
   328→  }
   329→
   330→  // 温度パラメータのチェック
   331→  if (node.data.temperature !== undefined) {
   332→    const temp = node.data.temperature;
   333→    if (typeof temp !== 'number' || temp < 0 || temp > 2) {
   334→      context.issues.push({
   335→        level: 'error',
   336→        path: `workflow.graph.nodes[${index}].data.temperature`,
   337→        message: `無効な温度パラメータ: ${temp}`,
   338→        suggestion: '0.0から2.0の範囲で指定してください',
   339→      });
   340→    } else if (temp > 1.0) {
   341→      context.issues.push({
   342→        level: 'warning',
   343→        path: `workflow.graph.nodes[${index}].data.temperature`,
   344→        message: `温度パラメータが高すぎる可能性があります（${temp}）`,
   345→        suggestion: '一般的な範囲は0.0-1.0です。創造的な出力が必要な場合は0.7-0.9が適切です',
   346→        autoFixable: true,
   347→        fixId: 'high-temperature',
   348→      });
   349→    }
   350→  }
   351→}
   352→
   353→function validateHTTPNode(context: ValidationContext, node: any, index: number): void {
   354→  if (node.data.url && !isValidURL(node.data.url)) {
   355→    context.issues.push({
   356→      level: 'error',
   357→      path: `workflow.graph.nodes[${index}].data.url`,
   358→      message: '無効なURL形式です',
   359→      suggestion: '有効なHTTP/HTTPSのURLを指定してください',
   360→    });
   361→  }
   362→
   363→  const validMethods = ['GET', 'POST', 'PUT', 'DELETE', 'PATCH', 'HEAD', 'OPTIONS'];
   364→  if (node.data.method && !validMethods.includes(node.data.method.toUpperCase())) {
   365→    context.issues.push({
   366→      level: 'error',
   367→      path: `workflow.graph.nodes[${index}].data.method`,
   368→      message: `無効なHTTPメソッド: ${node.data.method}`,
   369→      suggestion: `有効なメソッド: ${validMethods.join(', ')}`,
   370→    });
   371→  }
   372→}
   373→
   374→function validateEdges(context: ValidationContext): void {
   375→  const { dsl } = context;
   376→  const edges = dsl.workflow?.graph?.edges || [];
   377→  const nodes = dsl.workflow?.graph?.nodes || [];
   378→  const nodeIds = new Set(nodes.map((n) => n.id));
   379→
   380→  edges.forEach((edge, index) => {
   381→    if (!edge.source) {
   382→      context.issues.push({
   383→        level: 'error',
   384→        path: `workflow.graph.edges[${index}].source`,
   385→        message: 'エッジのsourceが必須です',
   386→        suggestion: '接続元のノードIDを指定してください',
   387→      });
   388→    } else if (!nodeIds.has(edge.source)) {
   389→      context.issues.push({
   390→        level: 'error',
   391→        path: `workflow.graph.edges[${index}].source`,
   392→        message: `存在しないノードへの参照: ${edge.source}`,
   393→        suggestion: '有効なノードIDを指定してください',
   394→      });
   395→    }
   396→
   397→    if (!edge.target) {
   398→      context.issues.push({
   399→        level: 'error',
   400→        path: `workflow.graph.edges[${index}].target`,
   401→        message: 'エッジのtargetが必須です',
   402→        suggestion: '接続先のノードIDを指定してください',
   403→      });
   404→    } else if (!nodeIds.has(edge.target)) {
   405→      context.issues.push({
   406→        level: 'error',
   407→        path: `workflow.graph.edges[${index}].target`,
   408→        message: `存在しないノードへの参照: ${edge.target}`,
   409→        suggestion: '有効なノードIDを指定してください',
   410→      });
   411→    }
   412→  });
   413→}
   414→
   415→// ヘルパー関数
   416→function hasNestedProperty(obj: any, path: string): boolean {
   417→  const parts = path.split('.');
   418→  let current = obj;
   419→
   420→  for (const part of parts) {
   421→    if (!current || typeof current !== 'object' || !(part in current)) {
   422→      return false;
   423→    }
   424→    current = current[part];
   425→  }
   426→
   427→  return true;
   428→}
   429→
   430→function isValidEmoji(str: string): boolean {
   431→  const emojiRegex = /^(\p{Emoji_Presentation}|\p{Emoji}\uFE0F)$/u;
   432→  return emojiRegex.test(str);
   433→}
   434→
   435→function isValidHexColor(color: string): boolean {
   436→  return /^#[0-9A-F]{6}$/i.test(color);
   437→}
   438→
   439→function isValidURL(url: string): boolean {
   440→  try {
   441→    new URL(url);
   442→    return true;
   443→  } catch {
   444→    return false;
   445→  }
   446→}
