    const [currentMajor] = CURRENT_DSL_VERSION.split('.').map(Number);

    if (importedMajor !== currentMajor) {
      context.issues.push({
        level: 'error',
        path: 'version',
        message: `DSLバージョン${dsl.version}は現在のバージョン${CURRENT_DSL_VERSION}と互換性がありません`,
