      });
    } else if (dsl.version !== CURRENT_DSL_VERSION) {
      context.issues.push({
        level: 'warning',
        path: 'version',
        message: `DSLバージョン${dsl.version}は最新バージョン${CURRENT_DSL_VERSION}と異なります`,
        suggestion: `最新機能を利用するには version: "${CURRENT_DSL_VERSION}" に更新してください`,
      });
