import { readFileSync } from 'fs';
import { validateDSLTool } from './src/mastra/tools/validate_dsl';

async function testValidation() {
  try {
    const yamlContent = readFileSync('./line-agent.yml', 'utf8');

    console.log('Testing validation with line-agent.yml...\n');

    const result = await validateDSLTool.execute({
      context: {
        dsl_yaml: yamlContent,
        validation_level: 'normal'
      }
    });

    console.log('Validation Result:');
    console.log('Valid:', result.valid);

    if (result.errors.length > 0) {
      console.log('\n❌ Errors:');
      result.errors.forEach((error, i) => {
        console.log(`${i + 1}. Path: ${error.path}`);
        console.log(`   Message: ${error.message}`);
        console.log(`   Suggestion: ${error.suggestion || 'None'}\n`);
      });
    }

    if (result.warnings.length > 0) {
      console.log('⚠️  Warnings:');
      result.warnings.forEach((warning, i) => {
        console.log(`${i + 1}. Path: ${warning.path}`);
        console.log(`   Message: ${warning.message}`);
        console.log(`   Suggestion: ${warning.suggestion || 'None'}\n`);
      });
    }

    if (result.info.length > 0) {
      console.log('ℹ️  Info:');
      result.info.forEach((info, i) => {
        console.log(`${i + 1}. Path: ${info.path}`);
        console.log(`   Message: ${info.message}\n`);
      });
    }

    if (result.auto_fixable.length > 0) {
      console.log('🔧 Auto-fixable issues:', result.auto_fixable);
    }

    console.log(result.valid ? '\n✅ Validation PASSED!' : '\n❌ Validation FAILED');

  } catch (error) {
    console.error('Error during validation:', error);
  }
}

testValidation();

