      path: 'workflow.graph',
      message: `循環参照が検出されました: ${cyclePath}`,
      suggestion: 'ワークフローには循環参照を含めることはできません。フローを見直してください',
    });
  });
}

function detectCycles(nodeMap: Map<string, DifyNode>, edges: DifyEdge[]): string[][] {
  const cycles: string[][] = [];
  const visited = new Set<string>();
