  const nodes = dsl.workflow.graph.nodes || [];
  const edges = dsl.workflow.graph.edges || [];

  // ノードとエッジのマップを作成
  nodes.forEach((node) => context.nodeMap.set(node.id, node));
  edges.forEach((edge) => context.edgeMap.set(edge.id, edge));

  // 各種論理検証を実行
