    context.issues.push({
      level: 'error',
      path: 'workflow.graph.nodes',
      message: 'ワークフローにはstartノードが必須です',
      suggestion: 'ワークフローの開始点となるstartノードを追加してください',
      autoFixable: true,
      fixId: 'missing-start-node',
